USE smartphone_wholesale_retail_db;

-- Basic business KPIs--

-- Total Revenue generated by the business per year

SELECT YEAR(sale_date) AS Accounting_Year,SUM(total_amount) AS Total_Revenue
FROM sales
GROUP BY YEAR(sale_date);

-- Total Transactions
SELECT COUNT(*) AS Total_transactions
FROM sales;


-- We calculate the Average order value (AOV)

SELECT  YEAR(sale_date) AS Accounting_Year, ROUND(AVG(total_amount),2) AS AOV
FROM sales
GROUP BY Year(sale_date);

-- Total Units sold

SELECT SUM(quantity) AS total_units_sold
FROM sale_items;

-- Total Customers (How many unique customers purchased from us)

SELECT COUNT(DISTINCT customer_id) AS Total_customers 
FROM sales;


-- Looking into sales performance
-- Calculating Monthly sales , Calculating monthly transaction count , Monthly avg order value

SELECT YEAR(sale_date) AS sales_year,MONTH(sale_date) as Months,SUM(net_amount) AS total_sales,COUNT(*) as Transaction_count, AVG(net_amount) AS average_monthly_sale
FROM sales
GROUP BY YEAR(sale_date),MONTH(sale_date);


-- Revenue by transaction type 

SELECT transaction_type,sum(net_amount) as revenue
FROm sales 
GROUP BY transaction_type;

-- Highest revenue month

SELECT YEAR(sale_date) AS sales_year, MONTH(sale_date) AS sales_month, SUM(net_amount) AS monthly_revenue
FROM sales
GROUP BY YEAR(sale_date), MONTH(sale_date)
ORDER BY monthly_revenue DESC
LIMIT 1;

--  Customer purchase history
-- Display customer name, total number of purchases, and total amount spent. Include customers who have never purchased anything.

SELECT c.customer_name,c.customer_id, COALESCE(count(s.sale_id),0) as total_number_of_purchases,sum(s.net_amount) as total_amount_spent
FROM customers c 
LEFT JOIN sales s 
ON c.customer_id = s.customer_id
GROUP BY c.customer_name,c.customer_id;


-- Top 10 customers
-- Find the top 10 customers based on total sales amount.

SELECT c.customer_name,c.customer_id,sum(s.net_amount) as total_amount_spent
FROM customers c 
JOIN sales s 
ON c.customer_id = s.customer_id
GROUP BY c.customer_name,c.customer_id
ORDER BY total_amount_spent DESC
LIMIT 10;


-- Product-wise sales
-- Display product name, brand name, quantity sold, and total revenue generated by each product.

SELECT p.product_name, b.brand_name,sum(s.quantity) as quantity_sold,SUM(s.unit_price * s.quantity) AS total_revenue
FROM products p
JOIN brands  b
ON p.brand_id=b.brand_id
JOIN sale_items s  
ON p.product_id = s.product_id
GROUP BY p.product_name, b.brand_name;


-- Brand performance
-- Calculate total revenue and quantity sold for every brand. Rank brands by revenue

SELECT b.brand_id,b.brand_name,SUM(s.quantity) AS Quantity_sold,SUM(s.quantity*s.unit_price) AS total_revenue, 
DENSE_RANK() OVER(ORDER BY SUM(s.quantity*s.unit_price) DESC) AS Brand_rank
FROM products p 
JOIN sale_items s    
ON p.product_id = s.product_id
JOIN brands b
ON p.brand_id=b.brand_id
GROUP BY b.brand_id,b.brand_name
;


-- Employee performance
-- Find the total number of sales transactions and total sales revenue handled by each employee.

SELECT e.employee_id,e.employee_name,COUNT(s.sale_id) AS sales_transactions, SUM(s.net_amount) AS total_revenue
FROM employees e 
JOIN sales s
ON e.employee_id=s.employee_id
GROUp BY e.employee_id,e.employee_name;



 -- Products never sold
-- Find products that have never appeared in any sale transaction.
SELECT p.product_id,p.product_name
FROM products p 
LEFT JOIN sale_items s  
ON p.product_id=s.product_id
WHERE s.product_id IS NULL;



 -- Supplier purchase analysis

-- Display each supplier's total purchase value and number of purchase transactions.

SELECT s.supplier_id,s.supplier_name,sum(p.total_amount) AS total_purchase_value, COUNT(purchase_id) AS Number_of_purchase
FROM suppliers s  
JOIN purchases p 
ON s.supplier_id=p.supplier_id
GROUP BY s.supplier_id,s.supplier_name;



-- Monthly customer acquisition


-- Find the number of new customers registered each month.

WITH first_purchase AS (
    SELECT customer_id, MIN(sale_date) AS first_purchase_date
    FROM sales
    GROUP BY customer_id
)

SELECT YEAR(first_purchase_date) AS year, MONTH(first_purchase_date) AS month, COUNT(customer_id) AS new_customers
FROM first_purchase
GROUP BY YEAR(first_purchase_date), MONTH(first_purchase_date)
ORDER BY year, month;

-- Average selling price
-- Calculate the average selling price of every product and compare it with its purchase cost, wherever the relevant data exists.


WITH sales_avg AS (
    SELECT product_id, AVG(unit_price) AS average_sell_price
    FROM sale_items
    GROUP BY product_id
),
purchase_avg AS (
    SELECT
    product_id,
    AVG(unit_cost) AS average_purchase_price
    FROM purchase_items
    GROUP BY product_id
)

SELECT p.product_id, p.product_name, ROUND(s.average_sell_price, 2) AS average_sell_price,
    ROUND(pr.average_purchase_price, 2) AS average_purchase_price
FROM products p
LEFT JOIN sales_avg s
ON p.product_id = s.product_id
LEFT JOIN purchase_avg pr
ON p.product_id = pr.product_id;


-- Inventory valuation
-- Calculate the total inventory value by product and brand using available stock and purchase cost.

WITH product_cost AS (
    SELECT product_id, SUM(quantity * unit_cost) / SUM(quantity) AS average_unit_cost
    FROM purchase_items
    GROUP BY product_id
)
SELECT p.product_id, p.product_name, b.brand_name, i.current_stock,ROUND(pc.average_unit_cost, 2) AS average_unit_cost,
    ROUND(i.current_stock * pc.average_unit_cost, 2) AS total_inventory_value
FROM products p
JOIN brands b
    ON p.brand_id = b.brand_id
JOIN inventory i
    ON p.product_id = i.product_id
JOIN product_cost pc
    ON p.product_id= pc.product_id
ORDER BY total_inventory_value DESC;


-- Above-average products
-- Find products whose total revenue is higher than the average product revenue.
SELECT p.product_name,p.product_id,SUM(s.quantity * s.unit_price) AS avg_product_revenue
FROM products p  
JOIN sale_items s  
ON p.product_id=s.product_id
GROUP BY p.product_name,p.product_id
HAVING SUM(s.quantity * s.unit_price) > (
    SELECT AVG(product_rev)
    FROM (
            SELECT SUM(quantity * unit_price) AS product_rev
            FROM sale_items
            GROUP BY product_id
        ) AS product_sales

   )
    ORDER BY avg_product_revenue DESC;



-- High-value customers
-- Find customers whose total spending is higher than the average customer spending.

SELECT c.customer_name,c.customer_id,SUM(s.net_amount) AS total_spending
FROM customers c
JOIN sales s  
ON c.customer_id=s.customer_id
GROUP BY c.customer_name,c.customer_id
HAVING (SUM(s.net_amount))>(
    SELECT AVG(customer_spending)
    FROM (
        SELECT customer_id, SUM(net_amount) AS customer_spending
        FROM sales
        GROUP BY customer_id
    ) AS customer_totals
)
ORDER BY total_spending DESC;

-- Monthly revenue comparison
-- Display monthly revenue alongside the previous month's revenue.

WITH monthly_revenue AS(
    SELECT MONTH(sale_date) AS MONTH, YEAR(sale_date) AS YEAR, SUM(net_amount) AS current_month_revenue
    FROM sales 
    GROUP BY MONTH(sale_date), YEAR(sale_date) 
)

SELECT *,LAG(current_month_revenue,1,0) OVER(order BY YEAR, MONTH  ) AS previous_year_revenue
FROM monthly_revenue;

-- Top-selling product per brand
-- Find the highest-revenue product within each brand


WITH product_sales AS (
    SELECT b.brand_id,b.brand_name,p.product_id,p.product_name,SUM(s.quantity) AS quantity_sold,
        SUM(s.quantity * s.unit_price) AS total_revenue
    FROM products p
    JOIN brands b
        ON p.brand_id = b.brand_id
    JOIN sale_items s
        ON p.product_id = s.product_id
    GROUP BY b.brand_id,b.brand_name,p.product_id,p.product_name
),
ranked_products AS (
    SELECT *,
        ROW_NUMBER() OVER ( PARTITION BY brand_id ORDER BY total_revenue DESC) AS product_rank
    FROM product_sales
)

SELECT *
FROM ranked_products
WHERE product_rank = 1;



-- Running revenue
-- Calculate cumulative revenue month by month.


WITH monthly_sales AS (
    SELECT YEAR(sale_date) AS year, MONTH(sale_date) AS month, SUM(net_amount) AS monthly_revenue
    FROM sales
    GROUP BY YEAR(sale_date), MONTH(sale_date)
)

SELECT year, month, monthly_revenue,
    SUM(monthly_revenue) OVER (
        ORDER BY year, month
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS cumulative_revenue
FROM monthly_sales;



-- Sales ranking
-- Rank employees based on their total revenue generated.


WITH employee_sales AS (
    SELECT e.employee_id, e.employee_name, COUNT(s.sale_id) AS total_transactions,
        SUM(s.net_amount) AS total_revenue
    FROM employees e
    JOIN sales s
        ON e.employee_id = s.employee_id
    GROUP BY e.employee_id,e.employee_name
)

SELECT *, DENSE_RANK() OVER (ORDER BY total_revenue DESC) AS employee_rank
FROM employee_sales
ORDER BY employee_rank;



-- Customer purchase frequency
-- Classify customers into one-time, occasional and frequent buyers based on transaction count. Define your own sensible thresholds.


WITH customer_orders AS (
    SELECT c.customer_id, c.customer_name, COUNT(s.sale_id) AS total_transactions
    FROM customers c
    LEFT JOIN sales s
        ON c.customer_id = s.customer_id
    GROUP BY c.customer_id, c.customer_name
)

SELECT customer_id, customer_name, total_transactions,
    CASE
        WHEN total_transactions = 0 THEN 'No Purchase'
        WHEN total_transactions = 1 THEN 'One-time Buyer'
        WHEN total_transactions BETWEEN 2 AND 5 THEN 'Occasional Buyer'
        ELSE 'Frequent Buyer'
    END AS customer_category
FROM customer_orders
ORDER BY total_transactions DESC;

SELECT *
FROM payments;

-- Payment collection analysis
-- Compare total sales amount with payments received and calculate outstanding balances, using the appropriate payment relationships.

WITH payment_summary AS (
    SELECT sale_id, SUM(amount) AS total_paid
    FROM payments
    GROUP BY sale_id
)

SELECT s.sale_id, s.customer_id, s.net_amount AS total_sales_amount,
    COALESCE(p.total_paid, 0) AS total_amount_paid,
    s.net_amount - COALESCE(p.total_paid, 0)
        AS outstanding_balance,
    CASE
        WHEN COALESCE(p.total_paid, 0) = 0
            THEN 'Unpaid'

        WHEN COALESCE(p.total_paid, 0) < s.net_amount
            THEN 'Partially Paid'

        WHEN COALESCE(p.total_paid, 0) = s.net_amount
            THEN 'Fully Paid'

        ELSE 'Overpaid'
    END AS payment_status
FROM sales s
JOIN payment_summary p
    ON s.sale_id = p.sale_id
ORDER BY outstanding_balance DESC;



-- Purchase versus sales


-- Compare monthly purchase value and monthly sales revenue to understand the difference in business activity.


WITH monthly_sales AS (
    SELECT YEAR(sale_date) AS year, MONTH(sale_date) AS month, SUM(net_amount) AS total_sales
    FROM sales
    GROUP BY YEAR(sale_date),MONTH(sale_date)
),

monthly_purchases AS (
    SELECT YEAR(purchase_date) AS year, MONTH(purchase_date) AS month, SUM(total_amount) AS total_purchases
    FROM purchases
    GROUP BY YEAR(purchase_date), MONTH(purchase_date)
)

SELECT COALESCE(s.year, p.year) AS year, COALESCE(s.month, p.month) AS month,
    COALESCE(s.total_sales, 0) AS total_sales,
    COALESCE(p.total_purchases, 0) AS total_purchases,
    COALESCE(s.total_sales, 0)
        - COALESCE(p.total_purchases, 0) AS sales_purchase_difference
FROM monthly_sales s
LEFT JOIN monthly_purchases p
    ON s.year = p.year AND s.month = p.month
ORDER BY year, month;



-- Business performance report
-- Create a consolidated monthly report containing revenue, transaction count, average order value, units sold, purchase value and payment collections.


WITH monthly_sales AS (
    SELECT YEAR(sale_date) AS year, MONTH(sale_date) AS month, COUNT(sale_id) AS total_transactions, SUM(net_amount) AS total_revenue,
        AVG(net_amount) AS average_order_value
    FROM sales
    GROUP BY YEAR(sale_date), MONTH(sale_date)
),

monthly_units AS (
    SELECT YEAR(s.sale_date) AS year, MONTH(s.sale_date) AS month, SUM(si.quantity) AS units_sold
    FROM sales s
    JOIN sale_items si
        ON s.sale_id = si.sale_id
    GROUP BY YEAR(s.sale_date), MONTH(s.sale_date)
),

monthly_purchases AS (
    SELECT YEAR(purchase_date) AS year, MONTH(purchase_date) AS month, SUM(total_amount) AS purchase_value
    FROM purchases
    GROUP BY YEAR(purchase_date), MONTH(purchase_date)
),

monthly_payments AS (
    SELECT YEAR(payment_date) AS year, MONTH(payment_date) AS month, SUM(amount) AS payments_collected
    FROM payments
    GROUP BY YEAR(payment_date), MONTH(payment_date)
)

SELECT s.year, s.month, s.total_revenue, s.total_transactions,
    ROUND(s.average_order_value, 2) AS average_order_value,
    COALESCE(u.units_sold, 0) AS units_sold,
    COALESCE(p.purchase_value, 0) AS purchase_value,
    COALESCE(pm.payments_collected, 0) AS payments_collected
FROM monthly_sales s
LEFT JOIN monthly_units u
    ON s.year = u.year AND s.month = u.month
LEFT JOIN monthly_purchases p
    ON s.year = p.year AND s.month = p.month
LEFT JOIN monthly_payments pm
    ON s.year = pm.year AND s.month = pm.month
ORDER BY s.year, s.month;
